solution.solution.cpp:
#include <cstdint>
#include <iterator>
#include <map>
#include <string>

struct Overlapped { std::uint32_t Offset; std::uint32_t OffsetHigh; };

void setOffset(Overlapped& ov, std::uint64_t position)
{
    ov.Offset = static_cast<std::uint32_t>(position & 0xFFFFFFFFu);
    ov.OffsetHigh = static_cast<std::uint32_t>(position >> 32);
}

std::uint64_t offsetOf(const Overlapped& ov)
{
    return (std::uint64_t{ ov.OffsetHigh } << 32) | ov.Offset;
}

class ChunkAssembler
{
public:
    explicit ChunkAssembler(std::uint64_t start = 0) : position_{ start } {}

    bool add(std::uint64_t offset, std::string data)
    {
        if (data.empty() || offset < position_) return false;
        const std::uint64_t end{ offset + data.size() };
        const auto next{ chunks_.lower_bound(offset) };
        if (next != chunks_.end() && next->first < end) return false;
        if (next != chunks_.begin())
        {
            const auto before{ std::prev(next) };
            if (before->first + before->second.size() > offset) return false;
        }
        chunks_.emplace(offset, std::move(data));
        return true;
    }

    std::string takeReady()
    {
        std::string out;
        for (auto it{ chunks_.find(position_) }; it != chunks_.end(); it = chunks_.find(position_))
        {
            position_ += it->second.size();
            out += it->second;
            chunks_.erase(it);
        }
        return out;
    }

    std::uint64_t position() const { return position_; }
    std::size_t pending() const { return chunks_.size(); }

private:
    std::uint64_t position_;
    std::map<std::uint64_t, std::string> chunks_;
};

unitTests:
TEST("64-bit offsets in two halves") {
    Overlapped ov{};
    setOffset(ov, 0x0000000500000010ull);
    CHECK_EQ(ov.Offset, 0x10u);
    CHECK_EQ(ov.OffsetHigh, 5u);
    CHECK_EQ(offsetOf(ov), 0x0000000500000010ull);
    setOffset(ov, 4096);
    CHECK(ov.Offset == 4096 && ov.OffsetHigh == 0);
    setOffset(ov, 0xFFFFFFFFFFFFFFFFull);
    CHECK(ov.Offset == 0xFFFFFFFFu && ov.OffsetHigh == 0xFFFFFFFFu);
    CHECK_EQ(offsetOf(ov), 0xFFFFFFFFFFFFFFFFull);
}
TEST("chunks in any order come out in file order") {
    ChunkAssembler a;
    CHECK(a.add(4, "EFGH"));
    CHECK_EQ(a.takeReady(), std::string(""));
    CHECK(a.add(8, "IJ"));
    CHECK_EQ(a.pending(), 2u);
    CHECK(a.add(0, "ABCD"));
    CHECK_EQ(a.takeReady(), std::string("ABCDEFGHIJ"));
    CHECK_EQ(a.position(), 10u);
    CHECK_EQ(a.pending(), 0u);
}
TEST("partial progress") {
    ChunkAssembler a{ 100 };
    CHECK(a.add(100, "xy"));
    CHECK(a.add(105, "z"));
    CHECK_EQ(a.takeReady(), std::string("xy"));
    CHECK_EQ(a.position(), 102u);
    CHECK(a.add(102, "123"));
    CHECK_EQ(a.takeReady(), std::string("123z"));
    CHECK_EQ(a.position(), 106u);
}
TEST("refused chunks") {
    ChunkAssembler a;
    CHECK(a.add(10, "abcd"));
    CHECK(!a.add(12, "zz"));
    CHECK(!a.add(8, "zzz"));
    CHECK(!a.add(13, "q"));
    CHECK(a.add(14, "e"));
    CHECK(a.add(8, "zz"));
    CHECK(!a.add(3, ""));
    CHECK(a.add(0, "01234567"));
    CHECK_EQ(a.takeReady(), std::string("01234567zzabcde"));
    CHECK(!a.add(5, "late"));
    CHECK_EQ(a.pending(), 0u);
}

